let systemData = {};

try {
  // อ่านข้อมูลจาก localStorage (หรือจะใช้ database แทนได้)
  const existingData = $node.context().get(nodeKey);
  systemData = existingData || {};
} catch (e) {
  systemData = {};
}

// Database Node - สำหรับบันทึกข้อมูล  
